/** @file  IFCUtil.cpp
 *  @brief Implementation of conversion routines for some common Ifc helper entities.
 */

#ifndef ASSIMP_BUILD_NO_IFC_IMPORTER

#include "AssetLib/IFC/IFCUtil.h"
